"""Versioned engineering report. Reads results; never invokes the candidate."""
from pathlib import Path
from dataclasses import asdict
import ast,json,hashlib,subprocess,difflib
from collections import Counter
from datetime import datetime,timezone
import xml.etree.ElementTree as ET

R=Path('reports');P='search_comp3_';C=Path('scratch/search_compositional_recovery_v3');ROOT=Path.cwd()
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(n):return json.loads((R/(P+n)).read_text(encoding='utf8'))
def rows(p):return [json.loads(s) for s in Path(p).read_text(encoding='utf8').splitlines() if s.strip()]
def write(n,v):
    with (R/(P+n)).open('x',encoding='utf8') as f:json.dump(v,f,indent=2,ensure_ascii=False,sort_keys=True)
def link(p,line=None):
    p=Path(p).resolve();return '['+p.name+']('+p.as_posix()+(':'+str(line) if line else '')+')'
def doc(n,title,body):
    limitations={
      '02_missing_operands':'Fresh limitation: INCOMPLETE recall is20/25. A required sort placeholder has no slot owner; five metalinguistic by/titled assignment cases are incorrectly INCOMPLETE despite supplied values. Typed state coverage is PARTIAL.',
      '03_negative_domains':'Fresh limitation: whole-word searchable-text ordering still loses exclusions. Negative grammatical heads such as exclude books by become a positive author plus an invented Books exclusion. An invented mandatory negative field is approximated as broad text. These cause critical false execution; the repair is PARTIAL.',
      '04_invented_facets':'Fresh limitation: the positive fallback proof does not govern all negative facet proposals. Five exclude books by cases invent an excluded Books category. Every final hard field still needs the same typed ownership proof; this fix is PARTIAL.',
      '05_canonical_title':'Fresh limitation: quoted canonical operands bypass the new recognizer because protected spans are masked; fallback uses a different vocabulary path. Five Fictiom subject repairs are refused, and optional numeric legacy evidence blocks other valid repaired queries. This fix is PARTIAL.',
      '06_ir_decisions':'Fresh limitation: correct precedence cannot repair wrongly owned evidence. Domain alternatives expressed with between/and execute; assignment references appear missing; optional numeric evidence survives from the old decision. Source-span consumption is not proof of semantic ownership.',
      '08_development':'Fresh qualification failed all five parser gates despite all exposed typed/execution decisions passing. The benchmark populations differ in semantics and cannot be treated as a longitudinal improvement/regression estimate. Do not mistake development results for generalization.',
      '11_independent':'Primary result: typed92/150 (61.33%), execution107/150 (71.33%), false25/100, missed18/50, hard operand mismatch26/57 executed contexts. INCOMPLETE20/25, AMBIGUOUS15/25, NOTICE11/25, UNSUPPORTED10/25, CONTRADICTORY15/25. Strict fields51/150. All99 strict failure traces are retained in search_comp3_acceptance_error_analysis.json. No candidate or gold change followed this capture.',
    }
    if n in limitations:body+='\n\n**Fresh acceptance finding:** '+limitations[n]
    with (R/(P+n+'.md')).open('x',encoding='utf8') as f:f.write('# '+title+'\n\n'+body+'\n')
def main():
    pre=load('preflight.json');assert all(sha(p)==h for p,h in pre['protected_files'].items())
    candidate=load('candidate_freeze.json');assert all(sha(p)==h for p,h in candidate['files'].items())
    inventory=[]
    parent=Path('scratch/search_smart_engineering/ownership_recovery')
    for p in C.glob('*.py'):
        old=parent/p.name;inventory.append({'path':str(p),'sha256':sha(p),'parent_path':str(old) if old.exists() else None,
            'parent_sha256':sha(old) if old.exists() else None,'change':'UNCHANGED_COPY' if old.exists() and sha(old)==sha(p) else 'MODIFIED_DERIVATION' if old.exists() else 'NEW',
            'diff':list(difflib.unified_diff(old.read_text(encoding='utf8').splitlines(),p.read_text(encoding='utf8').splitlines(),fromfile=str(old),tofile=str(p))) if old.exists() and sha(old)!=sha(p) else []})
    write('implementation_inventory.json',inventory)
    metrics={}
    metrics['C5C644']=load('final2_c5c_typed_decision_scoring.json')['overall']
    for name in ['c5e90','c5er150','smarteng150']:metrics[name]=load('final2_'+name+'_results.json')['summary']
    c5scored=rows(R/(P+'final2_c5c_scored_observations.jsonl'))
    from scripts.search_v2c_c5c_score import OPERANDS
    hardfail=[x['case_id'] for x in c5scored if x['execution'] and any(not a['correct'] and a['field'] in OPERANDS for a in x['assertions'])]
    assert not hardfail
    old={p['case_id']:p for p in rows(R/'search_v2c_smarteng_final_c5c_predictions.jsonl')}
    changes=[]
    fields=sorted(OPERANDS|{'semantic_text','intent','sort'})
    for p in rows(R/(P+'final2_c5c_predictions.jsonl')):
        o=old[p['case_id']];delta={f:{'old':o['actual_plan'].get(f),'new':p['actual_plan'].get(f)} for f in fields if o['actual_plan'].get(f)!=p['actual_plan'].get(f)}
        if o['typed_decision']!=p['typed_decision']:delta['decision']={'old':o['typed_decision'],'new':p['typed_decision']}
        if delta:changes.append({'case_id':p['case_id'],'changes':delta})
    write('c5c_changed_predictions.json',changes)
    perf=load('final_performance.json');native=load('final_native_contracts.json')
    independent=load('independent_metrics.json');overall=independent['overall']
    positives=sum(x['expected_execution'] for x in rows(R/(P+'independent_scored_observations.jsonl')))
    failures=load('independent_failures.json')
    critical=overall['critical_executed_operand_case_ids']
    gate=load('independent_gate_decision.json')
    suite=next(ET.parse(R/(P+'final2_regression.xml')).getroot().iter('testsuite'))
    report={'development_populations_separate':metrics,'C5C_executed_operand_mismatch_contexts':hardfail,
        'C5C_strict_scored_dimensions':metrics['C5C644']['strict_scored_dimension_match'],
        'C5C_full_failure_analysis':str(R/(P+'final2_c5c_failure_analysis.json')),'changed_C5C_predictions':len(changes),
        'pytest':suite.attrib,'fresh_acceptance':overall,'development_is_independent':False,
        'semantic_limits':'Strict literal string comparison is reported, not invented semantic equivalence. Structured advisory/topic objects without a scalar oracle remain unscored; no real ranking relevance measurement.'}
    write('development_report.json',report)
    tables='| Population | Typed | Execution | False execution | Missed valid |\n|---|---:|---:|---:|---:|\n'
    for name,m in metrics.items():
        if name=='C5C644':typed=m['typed_accuracy'];exe=m['execution_accuracy'];false=m['false_execution_rate'];miss=m['missed_execution_rate']
        else:typed=m['typed_accuracy'];exe=m['execution_accuracy'];false=m['false_execution'];miss=m['missed_execution']
        fmt=lambda v:str(v['numerator'])+'/'+str(v['denominator'])
        tables+='| '+name+' (exposed) | '+fmt(typed)+' | '+fmt(exe)+' | '+fmt(false)+' | '+fmt(miss)+' |\n'
    fmt=lambda v:str(v['numerator'])+'/'+str(v['denominator'])
    tables+='| Fresh independent | '+fmt(overall['typed_accuracy'])+' | '+fmt(overall['execution_accuracy'])+' | '+fmt(overall['false_execution'])+' | '+fmt(overall['missed_execution'])+' |\n'
    doc('01_inherited_integrity','Inherited candidate and integrity',f'''Inherited `search-smarteng-disabled-compositional-2`, verified its 38-entry candidate freeze and 222-file evidence freeze, and all 2,224 protected historical entries before implementation. The protected union is {len(pre['protected_files'])} paths including manifest/verification metadata. The original 462 production entries remain unchanged. All final code is new, disabled candidate 3 under {link(C)}. No tracked or staged files changed.\n\nParent manifest: {link(R/'search_v2c_smarteng_candidate_freeze.json')}; preflight: {link(R/(P+'preflight.json'))}. Parent source and failed historical outcomes are untouched.''')
    doc('02_missing_operands','Missing operand investigation',f'''The inherited IR inferred missingness from a limited prose vocabulary. Delimited placeholders reached native scalar extraction as literal strings or were ignored; absent required fields then became unconstrained executable plans. Empty, omitted and unresolved evidence were also compressed into None without an explicit state.\n\n{link(C/'operands.py')} adds explicit OperandState values: PRESENT_RESOLVED, PRESENT_EMPTY, REQUIRED_OMITTED, EXPLICIT_PLACEHOLDER, UNRESOLVED_REFERENCE, UNKNOWN_MANDATORY_RELATIONSHIP, OPTIONAL_UNSUPPLIED, CONTRADICTORY, UNSUPPORTED and PRESENT_ADVISORY. A None scalar now has an explicit ledger state and ownership. Structural delimiters and dangling field syntax license a missing operand independently of placeholder wording. Quoted interiors remain opaque. Optional slots are advisory, and missing-word vocabulary in complete unquoted bibliographic operands is not itself missing evidence. Source spans remain mapped to original text.\n\nThe five formerly regressed C5C ellipsis cases are now INCOMPLETE; all 25 exposed Smart Engineering incomplete contexts are recognized. Focused tests include reordered complete intersections, deleted operands, arbitrary placeholder contents and literal Missing/Empty/Unknown names. This finite coverage is not a universal language guarantee.''')
    doc('03_negative_domains','Negative constraint ownership',f'''The inherited text-negative recognizer omitted WITHOUT even though the production whole-word predicate supported it. The explicit negative operator family now includes WITHOUT and BUT NOT, preserving the same normalized term and word boundaries used by native matches. Category exclusions go to exclude_subjects; format exclusions go to excluded_formats; searchable text goes to exclude_terms. Unsupported field-specific author/title negation is represented and blocked, rather than becoming a positive entity or a broader text predicate. Negative availability retains the established typed unsupported/conflict behavior.\n\nPipeline: source owner/operator → source-bound Candidate → Requirement + domain state → QueryPlan exclusion list → native matches after hydration. Production word normalization and `(?<!\\w)` / `(?!\\w)` boundaries remain unchanged; Marsh/ar tests pass. See {link(C/'query_ir.py')}, {link(C/'test_composition.py')} and {link(R/(P+'requalified_retrieval_contracts_final.json'))}.''')
    doc('04_invented_facets','Inherited facet fallback investigation',f'''Legacy _parse_legacy could promote the noun left after extracting other fields to a category. Global vocabulary made the grammatical noun Records a hard facet. {link(C/'ownership.py')} now requires proof from a supported explicit subject owner, a complete scoped category expression, established category-first bibliographic/topical grammar, or supported postfix category syntax. The same rule applies to every category, including aliases; no Records-specific exception exists. Unsupported inherited proposals are removed and recorded in query_ir.rejected_unowned_facets.\n\nDevelopment tests pair ordinary prose with explicit category ownership for Records, Maps, History and Physics. The initial ownership attempt was too restrictive and lost historical category-first positives; all failed test reports remain. The final rule preserves the broad inherited regression suite. General natural-language meaning still needs fresh validation.''')
    doc('05_canonical_title','Canonical repair and title refusal investigation',f'''A fully owned category correction and quoted title left a grammatical noun frame under a mandatory Require clause. It was then classified as an unrepresented mandatory operation. Recognized bibliographic noun frames are consumed without erasing unknown required operations. Explicit canonical correction retains bounded scoped vocabulary resolution, repair source coordinates and notices; quoted title content is not repaired.\n\nThe five exposed refusals now produce EXECUTABLE_WITH_NOTICE. The same candidate FacetVocabulary is used by understanding and extracted native correction apply/keep transforms. The later performance change preserves the native candidate eligibility, ratios, .86 threshold, .05 tie margin and unique scoped edit fallback using length/token buckets. It is not a probability or broad fuzzy permission. See {link(C/'vocabulary.py')} and {link(R/(P+'final_native_contracts.json'))}.''')
    doc('06_ir_decisions','Updated IR and decision composition',f'''The candidate retains the source ownership architecture and existing QueryPlan/C4 interfaces. Pure stages are source repair protection, modality ownership, structural operand states, domain/operator extraction, shared numeric/format grammar, facet proof, soft semantic residue, repair provenance and final typed composition. No actor or tenant authority is parsed from text.\n\nActual decision precedence is contradiction → incomplete → ambiguous → unsupported, with native contradiction/capability validation and compatibility evidence retained. Pending alternatives are not treated as simultaneous mandatory conjuncts: participating candidates become unresolved before validation. Complete conflicting values are left to native contradiction guards. Validation preserves the explanation ledger when scope capability checks replace a decision. One resolved condition cannot authorize a second unresolved required operand. The original six decision names and EXACT behavior are retained. Code: {link(C/'parser.py')}, {link(C/'query_ir.py')}; executable precedence tests: {link(C/'test_composition.py')}.''')
    doc('07_source_inventory','Actual changed source and lineage',f'''Machine-readable exact hashes and derivation diffs: {link(R/(P+'implementation_inventory.json'))}.\n\nModified derivations: parser.py (composition/ownership/metadata), query_ir.py (typed slots, negatives and alternative ownership), vocabulary.py (shared resolution and indexed enumeration). New modules: operands.py, ownership.py and test_composition.py. source_repair.py, __init__.py and inherited ownership/native-choice tests are unchanged copies. Shared frozen C5E-R grammar, QueryPlan, C4 and source repair dependencies remain protected. New harnesses/scripts/report files are inventoried in the final evidence manifest. No production implementation was edited.''')
    doc('08_development','Development regression results',tables+f'''\nAll four development cohorts are exposed. None is credited as fresh evidence. Final pytest: {suite.attrib['tests']} tests, {suite.attrib['failures']} failures, {suite.attrib['errors']} errors. Changed C5C predictions: {link(R/(P+'c5c_changed_predictions.json'))}; each other cohort has a complete changed_predictions list in its final results. No gold was changed.\n\nTyped and execution accuracy do not imply full semantic accuracy. C5C strict scored dimensions are {fmt(metrics['C5C644']['strict_scored_dimension_match'])}; 443 contexts have at least one strict mismatch, including semantic strings, affected-field reporting and intent. No executed C5C positive has a scored hard-operand mismatch. Full failure artifacts are preserved, including the initial unsuccessful regression attempts.''')
    doc('09_operand_preservation','Structured operand preservation',f'''No executed exposed-development positive has a scored hard-field loss/invention under its frozen masks. C5C: 0/250 executed positive contexts; C5E: 0/30; C5E-R: 0/50; Smart Engineering: 0/50. These are distinct populations, not pooled safety estimates. Fresh critical executed operand cases: {len(critical)}; full exact IDs and field comparisons: {link(R/(P+'independent_scored_observations.jsonl'))}.\n\nThe adapter scores literal scalar references and formats-only BOTH equivalence. Unknown/structured assertions remain unscored. This does not establish universal requirement preservation, title-domain semantics or real retrieval relevance. Mandatory unavailable fields block execution; unsupported negative domains are not approximated.''')
    doc('10_native_choices','Native notices, choices and limits',f'''Fifty read-only exact native schema/transform/load checks passed: {link(R/(P+'final_native_contracts.json'))}. Raw query >150 counts: C5E 90/90, C5E-R 138/150, previous Smart Engineering 35/150. These counts concern raw echoed ChoiceRequest.query; the limit is not an option-label limit. Short/long correction transforms preserve the other fields in isolation, but a >150 request cannot reach them through the current API. Placeholder completion rejects422. No truncation, request bound change, token or persistent protocol was introduced.\n\nThe actual load_choice read checks preserve owner/login/scope/workspace, raw query, session ID, parser version and expiry. They do not qualify real membership authorization or Mongo CAS/durability. Required integration alternatives and safe span completion proposal: {link(R/(P+'staging_proposal.md'))}.''')
    doc('11_independent','Fresh independent qualification',f'''One primary evaluation; fresh gold-blind capture after candidate/gold/masks/evaluator/structural audit/contract freeze. Author and reviewer are separate AI agents; human reviewers=0, actual model identity=NOT_EXPOSED. Reviewer saw only the query/context packet and normative contracts, not predictions, author labels or desired pass rates.\n\n{tables}\nPer-stratum results and all30 cells: {link(R/(P+'independent_metrics.json'))}; unchanged audit including sealed counts only: {link(R/(P+'final_structural_isolation.json'))}. Gates: {link(R/(P+'independent_gate_decision.json'))}. Candidate/gold were not changed after capture; no retry/rescore of revised code was presented as fresh. All errors and operand mismatches are retained. Finite150-context validation and AI review do not establish zero real-world risk.''')
    doc('12_library_retrieval','Public/private compatibility and retrieval',f'''The exact protected native function harness passes40 local-library cases under global EMPTY/INACCESSIBLE dependencies plus8 actual global execution fixture cases. All five parser scopes use repository-authoritative capability projections. Institutional unlinked books remain discoverable, foreign rows are excluded and global dependency reads are zero in the isolated local fixtures. See {link(R/(P+'requalified_offline_native_components_final.json'))} and {link(R/(P+'requalified_retrieval_contracts_final.json'))}.\n\nThe global semantic provider is fixed-ID synthetic. Tests verify topic transport, filters after native hydration, empty results, pagination and serialization; there is no independent real embedding/ranking relevance oracle. New focused native matches tests cover simultaneous filters, ranges/availability in the inherited suite, exclusions, entity intersections, optional preferences and corrections. Native title_text currently matches title OR author; title-only enforcement would require a separate contract change. Full HTTP/JWT/current membership and cross-worker durability are unverified. Source extraction avoids backend.database.mongodb import-time index writes and status reads that may mutate stale metadata.''')
    a=perf['results']['after'];b=perf['results']['before']
    doc('13_performance','Profiling and matched performance',f'''Profile source: {link(R/(P+'profile_before.txt'))}; indexed source profile: {link(R/(P+'final_profile_after.txt'))}. Repeated full vocabulary scans and duplicate edit-distance enumeration dominated avoidable work; the indexed version preserves candidate eligibility and exact complete plan hashes for150/150 matched queries.\n\nSame exposed C5E-R150 workload: serial p50 {b['serial']['p50_ms']:.2f} → {a['serial']['p50_ms']:.2f} ms; p95 {b['serial']['p95_ms']:.2f} → {a['serial']['p95_ms']:.2f}; max {b['serial']['max_ms']:.2f} → {a['serial']['max_ms']:.2f}. Four-worker p95 {b['four_workers']['p95_ms']:.2f} → {a['four_workers']['p95_ms']:.2f}; max {b['four_workers']['max_ms']:.2f} → {a['four_workers']['max_ms']:.2f}. Each revision300 calls (150 serial+150 concurrent), errors0/300, deterministic150/150. Final CPU {a['CPU_ms']:.2f}ms, RSS {a['rss_before']} → {a['rss_after']} bytes.\n\nSingle shared host and fixed order limit inference. The initial comparison used an earlier semantic revision and failed a complete-plan-hash assertion; it is preserved and not used as an optimization claim. Corrected matched measurement restores preoptimization scans into otherwise identical final code. No agreed SLO exists; no operational PASS. Full-search, Mongo and real-vector latency N/A. {link(R/(P+'final_performance.json'))}.''')
    doc('14_staging','Operational staging prerequisites',f'''Staging readiness is BLOCKED. Current authorization prohibits even disposable Mongo writes. Real JWT/API/membership, choice issuance and CAS/one-use/expiry durability, structural completion and >150 choice queries, actual vector relevance/health, concurrent end-to-end load and agreed SLOs remain required. No current resident health check ran; the last recorded health is STALE/degraded with baseline_verified=False.\n\nConcrete future disposable staging plan: {link(R/(P+'staging_proposal.md'))}. It includes exact namespace safety, startup index writes, fixture role matrix, paired index generation, cleanup and rollback. No fake staging or ranking metric is provided.''')
    doc('15_integration_rollback','Production integration and rollback',f'''Production activation is separately authorized. Review the concrete staging contract changes before any route/version change; native parser/session/choice imports must select one coherent parser generation across workers. Preserve old accepted-state/choice version semantics and fail closed on incompatibility. Rollout and rollback must include routing, pending contexts and paired semantic generation. The complete proposal is {link(R/(P+'staging_proposal.md'))}. No production routing, authorization, C4 policy, Mongo data, HNSW/KG, Qwen, frontend, recommendations, More Like This, RAG, staff inventory or circulation workflow was changed. The historical5,000,000 observation is not a current poll; no catalog reduction ran.''')
    doc('16_preservation','Evidence preservation',f'''All {len(pre['protected_files'])} protected union entries and the frozen candidate sources are byte-verified. Historical2224 and original production462 are included. No tracked/staged changes. Complete new evidence/source hashes and final verification are provided by {link(R/(P+'freeze_manifest.json'))} and {link(R/(P+'freeze_verification.json'))}. Earlier failed experiments and independent outcomes remain untouched. Mongo writes0, production activation0, HNSW/KG rebuilds0, resident health polls0, heldout evaluations0. The sealed auditor may project structural metadata internally; no heldout text, labels or identifiers were emitted.''')
    required={
        'FINAL':'PARTIAL','CANDIDATE_ID':candidate['candidate_id'],'ARCHITECTURE_STATUS':'Retained compositional IR; fresh safety failed because ownership/relationship coverage and inherited fallback authorization remain incomplete.',
        'PRODUCTION_READINESS':'BLOCKED','CANDIDATE_ACTIVATED':False,
        'MISSING_OPERAND_FIX_STATUS':'PARTIAL: fresh INCOMPLETE20/25; missing sort and metalinguistic role defects remain.',
        'NEGATIVE_CONSTRAINT_FIX_STATUS':'PARTIAL/UNSAFE: equivalent operator/domain order and negative bibliographic heads still lose constraints or execute unsupported domains.',
        'INVENTED_FACET_FIX_STATUS':'PARTIAL: positive fallback proof implemented; five fresh negative Books facet inventions remain.',
        'CANONICAL_REPAIR_FIX_STATUS':'PARTIAL: unquoted development repairs pass; quoted fallback and advisory numeric decisions refuse fresh valid repairs.',
        'DEVELOPMENT_TYPED_ACCURACY':{k:v['typed_accuracy'] for k,v in metrics.items()},
        'DEVELOPMENT_EXECUTION_ACCURACY':{k:v['execution_accuracy'] for k,v in metrics.items()},
        'DEVELOPMENT_FALSE_EXECUTION':{k:v.get('false_execution',v.get('false_execution_rate')) for k,v in metrics.items()},
        'DEVELOPMENT_MISSED_EXECUTION':{k:v.get('missed_execution',v.get('missed_execution_rate')) for k,v in metrics.items()},
        'MANDATORY_OPERAND_PRESERVATION':{'development_critical_executed_contexts':{'C5C':{'numerator':0,'denominator':250},'C5E':{'numerator':0,'denominator':30},'C5ER':{'numerator':0,'denominator':50},'SmartEng':{'numerator':0,'denominator':50}},'fresh_critical_cases':critical,'fresh_executed_denominator':sum(x['execution'] is True for x in rows(R/(P+'independent_scored_observations.jsonl'))),'limits':'Frozen scalar masks only; not universal meaning/relevance.'},
        'INDEPENDENT_ACCEPTANCE_SIZE':150,'INDEPENDENT_TYPED_ACCURACY':overall['typed_accuracy'],'INDEPENDENT_EXECUTION_ACCURACY':overall['execution_accuracy'],
        'INDEPENDENT_FALSE_EXECUTION':overall['false_execution'],'INDEPENDENT_MISSED_EXECUTION':overall['missed_execution'],
        'INCOMPLETE_RECOGNITION':overall['per_kind_recall']['INCOMPLETE'],'AMBIGUITY_RECOGNITION':overall['per_kind_recall']['AMBIGUOUS'],
        'NOTICE_RECOGNITION':overall['per_kind_recall']['EXECUTABLE_WITH_NOTICE'],
        'SMART_MODE_STATUS':'Disabled candidate; measured development/one fresh acceptance, no deployment.',
        'EXACT_MODE_STATUS':'Inherited literal delegation and read-only fixture tests preserved.',
        'PRIVATE_LIBRARY_STATUS':'Read-only native function fixtures pass; live authorization unverified.',
        'PRIVATE_GLOBAL_INDEPENDENCE':'Own unlinked institution books pass global-empty/inaccessible fixtures; linked enrichment operationally unverified.',
        'NATIVE_AUTHORIZATION_STATUS':'Source-preserved; mocked context/read binding tests only, no fresh real JWT/current membership qualification.',
        'NATIVE_CHOICE_CONTRACT_STATUS':'BLOCKED: >150 raw query resolution and span completion require approved integration work.',
        'SEMANTIC_RETRIEVAL_STATUS':'Fixture-only filter/topic transport; real embeddings and relevance N/A.',
        'PARSER_P50':{'population':'Exposed C5ER150 serial','count':150,'ms':a['serial']['p50_ms']},'PARSER_P95':{'population':'Exposed C5ER150 serial','count':150,'ms':a['serial']['p95_ms']},
        'FOUR_WORKER_P95':{'population':'Exposed C5ER150 four-worker','count':150,'ms':a['four_workers']['p95_ms']},
        'STAGING_READINESS':'BLOCKED; proposal prepared, execution not authorized.','CURRENT_RUNTIME_HEALTH_VERIFIED':False,
        'PRODUCTION_SOURCE_CHANGED':False,'PRODUCTION_POLICY_CHANGED':False,'MONGO_MUTATIONS':0,'HNSW_REBUILDS':0,'KG_REBUILDS':0,'HELDOUT_EVALUATIONS':0,
        'HISTORICAL_EVIDENCE_PRESERVED':{'protected_union':len(pre['protected_files']),'historical_parent_entries':2224,'production_entries':462,'changed':0},
        'REMAINING_BLOCKERS':(['Fresh independent parser safety/quality gates failed.'] if not gate['parser_gates_passed'] else [])+['Native long query and structural completion integration.','Actual HTTP/JWT/current membership and Mongo CAS/one-use durability.','Real vector relevance and current index health.','Agreed staging SLO and end-to-end load/rollback qualification.','Finite AI-reviewed sample; structured semantic oracle gaps.'],
        'NEXT_AUTHORIZED_ACTION':'Review frozen source-ownership failure analysis for a future disabled development revision and genuinely new qualification. Staging proposal is prepared; production activation and all Mongo writes remain unauthorized.'}
    qa={'required_fields':required,'independent_gate_decision':gate,'primary_attempts':1,'candidate_changes_after_primary_capture':0,'gold_changes_after_primary_capture':0,
        'human_reviewers':0,'actual_author_reviewer_model_identity':'NOT_EXPOSED','required_field_count':len(required),'generated_at_utc':datetime.now(timezone.utc).isoformat()}
    write('final_qa.json',qa)
    text=tables+'\nFINAL=PARTIAL; PRODUCTION_READINESS=BLOCKED; candidate remains disabled.\n\n'
    for k,v in required.items():text+='- **'+k+'**: '+(json.dumps(v,ensure_ascii=False) if not isinstance(v,str) else v)+'\n'
    doc('17_final_qa','Final QA and readiness decision',text)
    reviewer=[]
    for p in C.glob('*.py'):
        for n in ast.walk(ast.parse(p.read_text(encoding='utf8'))):
            if isinstance(n,(ast.FunctionDef,ast.ClassDef)):reviewer.append({'file':str(p.resolve()),'symbol':n.name,'line':n.lineno})
    write('reviewer_map.json',reviewer)
    print(json.dumps({'FINAL':'PARTIAL','production':'BLOCKED','required_fields':len(required),'protected_verified':len(pre['protected_files'])}))
if __name__=='__main__':main()
